/**
 * Custom Worker entry. The Workers free plan allows ~10ms of CPU per request, and booting Next.js
 * takes a good share of that, so the hot paths are answered here directly:
 *   - rendered card images from KV
 *   - cached cards (< 6h old) and the board from D1, passing the stored JSON through unparsed
 * Only cache misses (first scans, rescans, image renders, share pages) go to the OpenNext handler.
 */
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";
import { BOARD_COUNTRY, LANGUAGES } from "./src/lib/board-config";

type KV = { get(key: string, type: "arrayBuffer"): Promise<ArrayBuffer | null> };
type D1 = {
  prepare(sql: string): {
    bind(...v: unknown[]): {
      first<T>(): Promise<T | null>;
      all<T>(): Promise<{ results: T[] }>;
    };
  };
};
type Env = { IMAGES?: KV; DB?: D1; SITE_URL?: string } & Record<string, unknown>;

const IMAGE_ROUTE = /^\/api\/card\/([A-Za-z0-9-]{1,39})\/image$/;
const CARD_ROUTE = /^\/api\/card\/([A-Za-z0-9-]{1,39})$/;
const SIX_HOURS_MS = 6 * 60 * 60 * 1000;
const ON_BOARD = "(country = ? OR country IS NULL)";

const CORS: Record<string, string> = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type",
};

function jsonBody(body: string, cache: string): Response {
  return new Response(body, {
    headers: { "Content-Type": "application/json; charset=utf-8", "Cache-Control": cache, ...CORS, "X-Specsheet-Fast": "1" },
  });
}

/** Make sure API responses coming out of Next.js always carry CORS headers (errors included). */
function withCors(res: Response): Response {
  if (res.headers.get("Access-Control-Allow-Origin")) return res;
  const out = new Response(res.body, res);
  for (const [k, v] of Object.entries(CORS)) out.headers.set(k, v);
  return out;
}

async function fastCard(db: D1, login: string): Promise<Response | null> {
  const row = await db
    .prepare("SELECT data, scanned_at, country, overall FROM cards WHERE login = ?")
    .bind(login.toLowerCase())
    .first<{ data: string; scanned_at: number; country: string | null; overall: number }>();
  if (!row || Date.now() - row.scanned_at >= SIX_HOURS_MS) return null;
  let rank: { rank: number; total: number } | null = null;
  if (row.country === null || row.country === BOARD_COUNTRY) {
    const r = await db
      .prepare(
        `SELECT (SELECT COUNT(*) FROM cards WHERE ${ON_BOARD} AND overall > ?) AS above,
                (SELECT COUNT(*) FROM cards WHERE ${ON_BOARD}) AS total`,
      )
      .bind(BOARD_COUNTRY, row.overall, BOARD_COUNTRY)
      .first<{ above: number; total: number }>();
    if (r) rank = { rank: r.above + 1, total: r.total };
  }
  // splice boardRank into the stored JSON object without parsing it
  const body = `${row.data.slice(0, row.data.lastIndexOf("}"))},"boardRank":${JSON.stringify(rank)}}`;
  return jsonBody(body, "public, max-age=60, s-maxage=600");
}

async function fastBoard(db: D1, langParam: string | null): Promise<Response | null> {
  const lang = langParam ? LANGUAGES.find((l) => l.toLowerCase() === langParam.toLowerCase()) : undefined;
  if (langParam && !lang) return null; // let the app produce the proper 400
  const sql = `SELECT data FROM cards WHERE ${ON_BOARD}${lang ? " AND top_language = ? COLLATE NOCASE" : ""}
               ORDER BY overall DESC, scanned_at DESC LIMIT 500`;
  const args: unknown[] = lang ? [BOARD_COUNTRY, lang] : [BOARD_COUNTRY];
  const { results } = await db.prepare(sql).bind(...args).all<{ data: string }>();
  return jsonBody(`{"cards":[${results.map((r) => r.data).join(",")}]}`, "public, max-age=30, s-maxage=60");
}

export default {
  async fetch(request: Request, env: Env, ctx: unknown): Promise<Response> {
    const url = new URL(request.url);
    const { pathname, search } = url;

    if (request.method === "OPTIONS" && pathname.startsWith("/api/")) {
      return new Response(null, { status: 204, headers: CORS });
    }

    // The pages live on the frontend (Vercel). Send people there, keeping old /u/<name> links working.
    const site = String(env.SITE_URL ?? "").replace(/\/$/, "");
    if (site && request.method === "GET" && new URL(site).host !== url.host) {
      if (pathname === "/" || pathname.startsWith("/u/") || ["/leaderboard", "/compare", "/binder"].includes(pathname)) {
        return Response.redirect(`${site}${pathname}${search}`, 301);
      }
    }

    if (request.method === "GET") {
      try {
        const img = pathname.match(IMAGE_ROUTE);
        if (img && env.IMAGES) {
          const f = url.searchParams.get("format");
          const format = f === "og" || f === "sheet" ? f : "card";
          const png = await env.IMAGES.get(`${format}:${img[1].toLowerCase()}`, "arrayBuffer");
          if (png) {
            return new Response(png, {
              headers: { "Content-Type": "image/png", "Cache-Control": "public, max-age=3600, s-maxage=21600", ...CORS, "X-Specsheet-Image": "kv" },
            });
          }
        }
        const card = pathname.match(CARD_ROUTE);
        if (card && env.DB && url.searchParams.get("rescan") !== "1") {
          const res = await fastCard(env.DB, card[1]);
          if (res) return res;
        }
        if (pathname === "/api/board" && env.DB) {
          const res = await fastBoard(env.DB, url.searchParams.get("lang"));
          if (res) return res;
        }
      } catch {
        /* fall through to the app */
      }
    }

    const res: Response = await handler.fetch(request, env, ctx);
    return pathname.startsWith("/api/") ? withCors(res) : res;
  },
};
